Section Leaf.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.
  Variables (F : bvmap 5 word) (fc : bv 32).
  Notation fx := (PropExec.mkFP F fc) (only parsing).

  Lemma fwritex_g : forall R M (sp ret s l f wpos wend lo shi : Z) bs,
    rfull R ->
    getr R 1%bv = Z_to_bv 64 ret -> 0 <= ret < 2 ^ 48 -> ret mod 2 = 0 ->
    getr R 2%bv = Z_to_bv 64 sp -> getr R 10%bv = Z_to_bv 64 s -> getr R 11%bv = Z_to_bv 64 l -> getr R 12%bv = Z_to_bv 64 f ->

    ninv lo shi M -> stk asegs M lo sp -> aceil <= lo -> lo + AINTRIN_STACK + 64 <= sp -> l <= 2 ^ 40 ->
    lo + 64 <= wpos -> wpos + l + 64 <= shi ->
    ((lo + 64 <= s /\ s + l + 64 <= shi /\ sp <= s) \/ (l = 0 /\ AIMG_LO + 64 <= s /\ s + 64 <= AIMG_TOP)) ->
    sp <= wpos -> sp <= f ->

    2 ^ 16 <= sp - 64 -> sp < 2 ^ 47 -> sp mod 16 = 0 -> mdef M (sp - 64) 64 ->
    2 ^ 16 <= f -> f + 232 < 2 ^ 47 -> (f + 232 <= sp - 64 \/ sp <= f) -> mdef M f 232 ->
    fld SEGS M (f + 32) 8 wend -> fld SEGS M (f + 40) 8 wpos -> fld SEGS M (f + 144) 4 (2 ^ 32 - 1) ->
    0 <= l -> wpos + l <= wend -> 2 ^ 16 <= wpos -> wend < 2 ^ 47 -> mdef M wpos l ->
    0 <= s -> s + l < 2 ^ 47 -> rdn SEGS M (Z_to_bv 64 s) (Z.to_nat l) = Some bs ->
    (wpos + l <= s \/ s + l <= wpos) -> (wpos + l <= f \/ f + 232 <= wpos) -> (wpos + l <= sp - 64 \/ sp <= wpos) ->
    (s + l <= sp - 64 \/ sp <= s) ->
    exists R' M',
      HExec.msteps SEGS (@mkst fx R (Z_to_bv 64 A_FWRITEX_A) M (seg_rom SEGS)) (@mkst fx R' (Z_to_bv 64 ret) M' (seg_rom SEGS))
      /\ rfull R'
      /\ getr R' 10%bv = Z_to_bv 64 l
      /\ (forall r, In r leaf_kept -> getr R' r = getr R r)
      /\ stores_in (fun a => zwin (sp - 64 - AINTRIN_STACK) sp a \/ zwin wpos (wpos + l) a \/ zwin (f + 40) (f + 48) a) M M'
      /\ fld SEGS M' (f + 40) 8 (wpos + l) /\ fld SEGS M' (f + 32) 8 wend /\ fld SEGS M' (f + 144) 4 (2 ^ 32 - 1)
      /\ ninv lo shi M' /\ stk asegs M' lo sp.
Proof.
